1	import { beforeEach, describe, expect, test } from "bun:test";
2	import { addAttractorOption, addComponentColumn, addForceRow, updateForceField } from "./actions";
3	import { emptyPendingState, mountForms, regenerateStagedCommands } from "./forms";
4	import { toCommandLines, type PendingState, type SnapshotAttractor, type SnapshotComponent, type SnapshotForce } from "./model";
5	
6	// ---------------------------------------------------------------------------
7	// Fixtures — a minimal PendingState plus a hand-built HTML fixture string
8	// mirroring the relevant slice of src/view/shell.html: the four
9	// `form[data-command-generator]` elements, the toolbar's two NEW visibility
10	// checkboxes (`data-show-proposed-toggle` / `data-show-unrelated-toggle`,
11	// not yet in shell.html itself — see the task's fixture design note), the
12	// live `<table class="matrix">` (mirroring matrix-interactions.test.ts's
13	// fixture shape so column-insertion assertions have real thead/tbody/tfoot
14	// structure to act on), `#staged-commands`, `#copy-staged`, `#clear-staged`.
15	//
16	// Design decisions pinned by these tests (documented per repo instructions):
17	//
18	// - Synthetic attractor id scheme (cli-schema.json's "add attractor" has NO
19	//   id flag — confirmed by reading web/generated/cli-schema.json directly):
20	//   `NEW-ATTR-<n>`, where n is one more than the max N found in existing
21	//   `state.addedAttractors` ids matching `/^NEW-ATTR-(\d+)$/` (max + 1, not
22	//   count + 1) — mirrors actions.ts's `addForceRow` tempId scheme exactly,
23	//   for the same collision-after-removal-proofing rationale.
24	// - Duplicate-component-name error UX: the component form gains a sibling
25	//   `<p data-component-form-error></p>` (present but empty in the fixture);
26	//   on a duplicate `addComponentColumn` throw, mountForms catches it, sets
27	//   that element's `.textContent` to a non-empty message, and adds
28	//   `aria-invalid="true"` to the form's `name` input — WITHOUT calling
29	//   `setState`, touching the table, or letting the exception escape the
30	//   submit handler. A subsequent successful (non-duplicate) submit clears
31	//   both the error text and the `aria-invalid` attribute.
32	// ---------------------------------------------------------------------------
