88	function forceRowHtml(force: SnapshotForce, components: SnapshotComponent[]): string {
89	  const total = force.components.length;
90	  const cells = components
91	    .map((c) => {
92	      const coupled = force.components.includes(c.name);
93	      return `<td data-residue-cell="true" data-force-id="${force.id}" data-component="${c.name}" data-coupled="${
94	        coupled ? "1" : "0"
95	      }">${coupled ? "1" : ""}</td>`;
96	    })
97	    .join("");
98	  return `<tr class="force-row" data-force-id="${force.id}" data-force-kind="${force.kind}">
99	      <th class="sticky-col" data-force-id="${force.id}"></th>
100	      ${cells}
101	      <td class="sticky-col-right" data-row-total="${total}">${total}</td>
102	    </tr>`;
103	}
