105	function fixtureTableHtml(state: PendingState): string {
106	  const components = [...state.baseComponents, ...state.addedComponents];
107	  const forces = [...state.baseForces, ...state.addedForces];
108	
109	  const headerCells = components
110	    .map((c) => `<th class="sticky-row" data-component="${c.name}">${c.name}</th>`)
111	    .join("");
112	  const rows = forces.map((f) => forceRowHtml(f as SnapshotForce, components)).join("");
113	  const footerCells = components.map((c) => `<td data-col-total="0" data-component="${c.name}">0</td>`).join("");
114	
115	  return `<table class="matrix">
116	      <thead><tr>
117	        <th class="sticky-col sticky-row corner">force</th>
118	        ${headerCells}
119	        <th class="sticky-row sticky-col-right corner">total</th>
120	      </tr></thead>
121	      <tbody>${rows}</tbody>
122	      <tfoot><tr>
123	        <th class="sticky-col corner">totals</th>
124	        ${footerCells}
125	        <td class="sticky-col-right corner" data-grand-total="0">0</td>
126	      </tr></tfoot>
127	    </table>`;
128	}
