130	function forceFormHtml(kind: "stressor" | "purpose"): string {
131	  return `<form data-command-generator="${kind}">
132	      <fieldset>
133	        <legend>${kind}</legend>
134	        <input name="description" type="text" />
135	        <input name="attractor_id" type="text" />
136	        <input name="naive_change" type="text" />
137	        <input name="shortname" type="text" />
138	        <input name="outcomes" type="text" />
139	        <button type="submit">stage</button>
