144	function fixtureHtml(state: PendingState): string {
145	  return `
146	    <div class="view-toolbar" data-view-toolbar>
147	      <input type="search" data-force-filter />
148	      <label><input type="checkbox" data-fusion-fission-filter /></label>
149	      <label><input type="checkbox" data-show-proposed-toggle checked /> show proposed</label>
150	      <label><input type="checkbox" data-show-unrelated-toggle checked /> show unrelated</label>
151	    </div>
152	    ${fixtureTableHtml(state)}
153	    ${forceFormHtml("stressor")}
154	    ${forceFormHtml("purpose")}
155	    <form data-command-generator="attractor">
156	      <fieldset>
157	        <legend>attractor</legend>
158	        <input name="name" type="text" />
159	        <input name="description" type="text" />
160	        <input name="positive_state" type="text" />
161	        <input name="negative_state" type="text" />
162	        <button type="submit">stage</button>
163	      </fieldset>
164	    </form>
165	    <form data-command-generator="component">
166	      <fieldset>
167	        <legend>component</legend>
168	        <input name="name" type="text" />
169	        <input name="description" type="text" />
170	        <input name="status" type="text" />
171	        <input name="architecture_set" type="text" />
172	        <button type="submit">stage</button>
173	      </fieldset>
174	      <p data-component-form-error></p>
175	    </form>
176	    <textarea id="staged-commands" readonly></textarea>
177	    <button type="button" id="copy-staged">copy</button>
178	    <button type="button" id="clear-staged">clear</button>
179	  `;
180	}
