182	function mountFixture(state: PendingState): {
183	  container: HTMLElement;
184	  getState: () => PendingState;
185	  setState: (next: PendingState) => void;
186	  changeCount: () => number;
187	} {
188	  document.body.innerHTML = fixtureHtml(state);
189	  const container = document.body;
190	
191	  let current = state;
192	  let changes = 0;
193	  const getState = (): PendingState => current;
194	  const setState = (next: PendingState): void => {
195	    current = next;
196	  };
197	
198	  mountForms(container, getState, setState, {
199	    onChange: () => {
200	      changes += 1;
201	    },
202	  });
203	
204	  return { container, getState, setState, changeCount: () => changes };
205	}
