207	function setInput(form: Element, name: string, value: string): void {
208	  const input = form.querySelector<HTMLInputElement>(`[name="${name}"]`);
209	  if (!input) throw new Error(`fixture setup failed: input "${name}" not found`);
210	  input.value = value;
211	}
