523	describe("mountForms — visibility toggles", () => {
524	  function hiddenComponents(table: Element): Set<string> {
525	    const hidden = new Set<string>();
526	    for (const el of Array.from(table.querySelectorAll("[data-component]"))) {
527	      const name = el.getAttribute("data-component");
528	      if (name === null) continue;
529	      const isHidden = el.hasAttribute("hidden") || (el as HTMLElement).hidden === true;
530	      if (isHidden) hidden.add(name);
531	    }
532	    return hidden;
533	  }
534	
535	  test("unchecking show-proposed hides every th/td for 'storage' (status: proposed) across thead/tbody/tfoot", () => {
536	    const state = baseState();
537	    const { container } = mountFixture(state);
538	    const table = container.querySelector("table.matrix");
539	    if (!table) throw new Error("fixture setup failed");
540	
541	    const toggle = container.querySelector<HTMLInputElement>("[data-show-proposed-toggle]");
542	    if (!toggle) throw new Error("fixture setup failed");
543	    toggle.checked = false;
544	    toggle.dispatchEvent(new Event("change", { bubbles: true }));
545	
546	    const hidden = hiddenComponents(table);
547	    expect(hidden.has("storage")).toBe(true);
548	    expect(hidden.has("cli")).toBe(false);
