1	// DOM-wiring layer for the live-editing NKP matrix (Phase 5 of
2	// residual/iterations/view-live-editing-plan.md). Attaches event listeners to
3	// an already-server-rendered `<table class="matrix">` (see
4	// src/view/components/matrix.rs for the exact markup contract this module
5	// binds to) and drives state transitions through the pure reducers in
6	// ./actions and the pure decision helpers in ./render-decisions /./model.
7	//
8	// This module owns DOM mutation only — it never invents business rules.
9	// Every state transition is delegated to toggleComponent / addForceRow /
10	// updateForceField (./actions); every "should this be marked invalid?"
11	// decision is delegated to computeInvalidMarks (./render-decisions).
12	//
13	// Design decisions (documented per repo instructions, pinned by
14	// matrix-interactions.test.ts):
15	//
16	// - `mount`'s third parameter is a plain `setState` callback (not a store);
17	//   an optional 4th-parameter `MountOptions.onChange` fires after every
18	//   state-mutating interaction, *after* `setState` has already been called,
19	//   so a later phase can hang command-textbox regeneration off it without
20	//   this module knowing anything about that textbox.
21	// - Double-click on a residue cell re-renders only that `<td>` in place
22	//   (updates `data-coupled` and text content) rather than the whole table —
23	//   cheaper, and the task spec explicitly allows either strategy.
24	// - Right-click on a `tr.force-row` (event delegated from the table, since
25	//   rows are added/removed dynamically) opens a minimal context menu
26	//   (`<ul role="menu">` with two `<li role="menuitem" data-action="...">`
27	//   entries: "Add row above" / "Add row below") appended to `document.body`
28	//   at the cursor position. Choosing an entry calls `addForceRow` with the
29	//   SAME kind (stressor/purpose) as the row that was right-clicked (reading
30	//   `data-force-kind`) — right-clicking a specific row is the only kind
31	//   signal available at that point, so inheriting it is the least surprising
32	//   default. The new row is inserted as a sibling `<tr class="force-row"
33	//   data-force-id="<tempId>">` immediately before/after the anchor row, and
34	//   rendered already in "edit mode": its `.force-detail` div starts visible
35	//   (not `hidden`) and shows `<input>`/`<select>` fields directly (no
36	//   read-only `<dl>`, no separate Edit button click needed) since a brand
37	//   new row has nothing meaningful to display in read-only form yet.
38	// - An existing row's non-NKP fields are only ever edited via an explicit
39	//   "Edit" `<button>` appended into `.force-detail` (after the `<dl>`) —
40	//   never via double-click (double-click is reserved for NKP cells).
41	//   Clicking "Edit" swaps `description` / `naive change` / `outcomes` `<dd>`s
42	//   for pre-filled `<input type="text">` elements and the `attractor` `<dd>`
43	//   for a `<select>` populated from `attractorOptions(state)` (current
44	//   attractor id pre-selected), and shows "OK"/"Cancel" buttons while hiding
45	//   "Edit".
46	// - "OK" calls `updateForceField` only for editable fields (description,
47	//   attractorId, naiveChangeOrFeature, outcomes) whose input/select value
48	//   differs from the value captured when "Edit" was clicked — NOT
49	//   unconditionally for all four. This deviates from an earlier draft of
50	//   this comment: `updateForceField` sets the field explicitly in
51	//   `updatedForces`/`addedForces` even when the new value equals the old
52	//   one, so an unconditional call is NOT a no-op for state-equality checks
53	//   (see matrix-interactions.test.ts's "clicking OK calls updateForceField
54	//   for the edited fields" test, which asserts `getState()` equals a state
55	//   produced by a single `updateForceField` call for only the one field the
56	//   test actually edited). After OK, the fields swap back to a read-only
57	//   `<dl>` showing the newly-saved values and "Edit" reappears.
58	// - "Cancel" discards the `<input>`/`<select>` values without calling
59	//   `updateForceField` at all, and swaps back to the read-only `<dl>` showing
60	//   the values that were current before "Edit" was clicked (which, since no
61	//   reducer ran, are simply the still-current `getState()` values).
62	// - Invalid-row marking: any force whose key is in
63	//   `computeInvalidMarks(state).invalidForceKeys` gets the CSS class
64	//   `"row-invalid"` applied to both its `th.sticky-col[data-force-id]`
65	//   sticky label cell AND its `tr.force-row` element, so a stylesheet can key
66	//   off either. `invalidComponentColumns` is walked generically (applying
67	//   `"row-invalid"`-equivalent marking to matching `th[data-component]`
68	//   header cells, were that set ever non-empty) even though it is always
69	//   empty today per render-decisions.ts's documented scoping — this module
70	//   does not special-case that emptiness, it just naturally does nothing
71	//   when the set is empty.
72	
73	import { addForceRow, toggleComponent, updateForceField } from "./actions";
74	import type { PendingState } from "./model";
75	import { attractorOptions, computeInvalidMarks } from "./render-decisions";
76	
77	/** Options controlling side effects mount() triggers beyond the DOM/state update itself. */
78	export interface MountOptions {
79	  /**
80	   * Called after every state-mutating interaction, once `setState` has
81	   * already been invoked with the new state. Lets a later phase (e.g. the
82	   * command-textbox regenerator) react to changes without this module
83	   * knowing about it.
84	   */
85	  onChange?: () => void;
86	}
87	
88	type EditableField = "description" | "attractorId" | "naiveChangeOrFeature" | "outcomes";
89	
90	interface EffectiveForceValues {
91	  description: string;
92	  attractorId: string;
93	  naiveChangeOrFeature: string;
94	  outcomes: string;
95	}
96	
97	/** Resolves the currently-effective (base/added merged with any pending update) text field values for a force key. */
98	function getEffectiveForceValues(state: PendingState, forceKey: string): EffectiveForceValues {
99	  const update = state.updatedForces[forceKey];
100	  const added = state.addedForces.find((f) => f.tempId === forceKey);
101	  const base = added ?? state.baseForces.find((f) => f.id === forceKey);
102	  return {
103	    description: update?.description ?? base?.description ?? "",
104	    attractorId: update?.attractorId ?? base?.attractorId ?? "",
105	    naiveChangeOrFeature: update?.naiveChangeOrFeature ?? base?.naiveChangeOrFeature ?? "",
106	    outcomes: update?.outcomes ?? base?.outcomes ?? "",
107	  };
108	}
109	
110	/** Resolves the currently-effective coupled-components list for a force key. */
111	function effectiveComponents(state: PendingState, forceKey: string): string[] {
112	  const added = state.addedForces.find((f) => f.tempId === forceKey);
113	  if (added !== undefined) return added.components;
114	  const base = state.baseForces.find((f) => f.id === forceKey);
115	  if (base === undefined) return [];
116	  return state.updatedForces[forceKey]?.components ?? base.components;
117	}
118	
119	/** Renders the "<id> · <name>" label used in the read-only attractor <dd>, matching src/view/components/matrix.rs's fixture shape. */
120	function getAttractorLabel(state: PendingState, attractorId: string): string {
121	  const attractor = [...state.baseAttractors, ...state.addedAttractors].find((a) => a.id === attractorId);
122	  return attractor ? `${attractor.id} · ${attractor.name}` : attractorId;
123	}
124	
125	function createTextInput(name: string, value: string): HTMLInputElement {
126	  const input = document.createElement("input");
127	  input.type = "text";
128	  input.name = name;
129	  input.value = value;
130	  return input;
131	}
132	
133	function createAttractorSelect(state: PendingState, selectedId: string): HTMLSelectElement {
134	  const select = document.createElement("select");
135	  for (const option of attractorOptions(state)) {
136	    const optionEl = document.createElement("option");
137	    optionEl.value = option.id;
138	    optionEl.textContent = option.name;
139	    select.appendChild(optionEl);
140	  }
141	  select.value = selectedId;
142	  return select;
143	}
144	
145	function createResidueCell(forceKey: string, componentName: string): HTMLTableCellElement {
146	  const td = document.createElement("td");
147	  td.setAttribute("data-residue-cell", "true");
148	  td.setAttribute("data-force-id", forceKey);
149	  td.setAttribute("data-component", componentName);
150	  td.setAttribute("data-coupled", "0");
151	  return td;
152	}
153	
154	/**
155	 * Attaches all live-editing interactions (cell toggle, row context menu,
156	 * field edit, invalid-row marking) to `table`, an already-present
157	 * `<table class="matrix">` server-rendered per src/view/components/matrix.rs.
158	 *
159	 * `getState`/`setState` give this module read/write access to the
160	 * caller-owned `PendingState` without owning it directly, mirroring the
161	 * reducer signatures in ./actions.
162	 */
163	export function mount(
164	  table: HTMLTableElement,
165	  getState: () => PendingState,
166	  setState: (next: PendingState) => void,
167	  options?: MountOptions,
168	): void {
169	  function applyInvalidMarks(): void {
170	    const { invalidForceKeys } = computeInvalidMarks(getState());
171	    const rows = table.querySelectorAll<HTMLTableRowElement>("tr.force-row[data-force-id]");
172	    for (const row of Array.from(rows)) {
173	      const forceKey = row.getAttribute("data-force-id");
174	      if (forceKey === null) continue;
175	      const invalid = invalidForceKeys.has(forceKey);
176	      row.classList.toggle("row-invalid", invalid);
177	      row.querySelector("th.sticky-col[data-force-id]")?.classList.toggle("row-invalid", invalid);
178	    }
179	  }
180	
181	  function appendEditButton(detail: HTMLElement, forceKey: string): void {
182	    const button = document.createElement("button");
183	    button.type = "button";
184	    button.textContent = "Edit";
185	    button.addEventListener("click", () => enterEditMode(detail, forceKey));
186	    detail.appendChild(button);
187	  }
188	
189	  function renderReadOnly(detail: HTMLElement, forceKey: string): void {
190	    detail.innerHTML = "";
191	    const values = getEffectiveForceValues(getState(), forceKey);
192	    const dl = document.createElement("dl");
193	    const addPair = (term: string, value: string): void => {
194	      const dt = document.createElement("dt");
195	      dt.textContent = term;
196	      const dd = document.createElement("dd");
197	      dd.textContent = value;
198	      dl.append(dt, dd);
199	    };
200	    addPair("id", forceKey);
201	    addPair("attractor", getAttractorLabel(getState(), values.attractorId));
202	    addPair("description", values.description);
203	    addPair("naive change", values.naiveChangeOrFeature);
204	    addPair("outcomes", values.outcomes);
205	    detail.appendChild(dl);
206	    appendEditButton(detail, forceKey);
207	  }
208	
209	  function enterEditMode(detail: HTMLElement, forceKey: string): void {
210	    detail.innerHTML = "";
211	    const state = getState();
212	    const values = getEffectiveForceValues(state, forceKey);
213	
214	    const descriptionInput = createTextInput("description", values.description);
215	    const naiveChangeInput = createTextInput("naiveChangeOrFeature", values.naiveChangeOrFeature);
216	    const outcomesInput = createTextInput("outcomes", values.outcomes);
217	    const attractorSelect = createAttractorSelect(state, values.attractorId);
218	
219	    const okButton = document.createElement("button");
220	    okButton.type = "button";
221	    okButton.textContent = "OK";
222	    const cancelButton = document.createElement("button");
223	    cancelButton.type = "button";
224	    cancelButton.textContent = "Cancel";
225	
226	    okButton.addEventListener("click", () => {
227	      let next = getState();
228	      const edited: Array<[EditableField, string]> = [
229	        ["description", descriptionInput.value],
230	        ["attractorId", attractorSelect.value],
231	        ["naiveChangeOrFeature", naiveChangeInput.value],
232	        ["outcomes", outcomesInput.value],
233	      ];
234	      for (const [field, value] of edited) {
235	        if (value !== values[field]) {
236	          next = updateForceField(next, forceKey, field, value);
237	        }
238	      }
239	      setState(next);
240	      renderReadOnly(detail, forceKey);
241	      applyInvalidMarks();
242	      options?.onChange?.();
243	    });
244	
245	    cancelButton.addEventListener("click", () => {
246	      renderReadOnly(detail, forceKey);
247	    });
248	
249	    detail.append(descriptionInput, naiveChangeInput, outcomesInput, attractorSelect, okButton, cancelButton);
250	  }
251	
252	  function wireLiveField(
253	    el: HTMLInputElement | HTMLSelectElement,
254	    eventName: "input" | "change",
255	    forceKey: string,
256	    field: EditableField,
257	  ): void {
258	    el.addEventListener(eventName, () => {
259	      setState(updateForceField(getState(), forceKey, field, el.value));
260	      applyInvalidMarks();
261	      options?.onChange?.();
262	    });
263	  }
264	
265	  function buildNewForceRow(tempId: string, kind: "stressor" | "purpose"): HTMLTableRowElement {
266	    const state = getState();
267	    const components = [...state.baseComponents, ...state.addedComponents];
268	    const values = getEffectiveForceValues(state, tempId);
269	
270	    const tr = document.createElement("tr");
271	    tr.className = "force-row";
272	    tr.setAttribute("data-force-id", tempId);
273	    tr.setAttribute("data-force-kind", kind);
274	    tr.setAttribute("data-row-total", "0");
275	
276	    const th = document.createElement("th");
277	    th.className = "sticky-col";
278	    th.setAttribute("data-force-id", tempId);
279	
280	    const detail = document.createElement("div");
281	    detail.className = "force-detail";
282	
283	    const descriptionInput = createTextInput("description", values.description);
284	    const naiveChangeInput = createTextInput("naiveChangeOrFeature", values.naiveChangeOrFeature);
285	    const outcomesInput = createTextInput("outcomes", values.outcomes);
286	    const attractorSelect = createAttractorSelect(state, values.attractorId);
287	
288	    wireLiveField(descriptionInput, "input", tempId, "description");
289	    wireLiveField(naiveChangeInput, "input", tempId, "naiveChangeOrFeature");
290	    wireLiveField(outcomesInput, "input", tempId, "outcomes");
291	    wireLiveField(attractorSelect, "change", tempId, "attractorId");
292	
293	    detail.append(descriptionInput, naiveChangeInput, outcomesInput, attractorSelect);
294	    th.appendChild(detail);
295	    tr.appendChild(th);
296	
297	    for (const component of components) {
298	      tr.appendChild(createResidueCell(tempId, component.name));
299	    }
300	
301	    const totalTd = document.createElement("td");
302	    totalTd.className = "sticky-col-right";
303	    totalTd.setAttribute("data-row-total", "0");
304	    totalTd.textContent = "0";
305	    tr.appendChild(totalTd);
306	
307	    return tr;
308	  }
309	
310	  function closeContextMenu(): void {
311	    for (const el of Array.from(document.querySelectorAll('[role="menu"]'))) {
312	      el.remove();
313	    }
314	  }
315	
316	  function handleAddRow(anchorRow: HTMLTableRowElement, action: "add-above" | "add-below"): void {
317	    const kind: "stressor" | "purpose" = anchorRow.getAttribute("data-force-kind") === "purpose" ? "purpose" : "stressor";
318	    const { state: nextState, tempId } = addForceRow(getState(), kind);
319	    setState(nextState);
320	
321	    const newRow = buildNewForceRow(tempId, kind);
322	    const parent = anchorRow.parentElement;
323	    if (parent !== null) {
324	      parent.insertBefore(newRow, action === "add-above" ? anchorRow : anchorRow.nextSibling);
325	    }
326	
327	    applyInvalidMarks();
328	    options?.onChange?.();
329	  }
330	
331	  function openContextMenu(event: MouseEvent, anchorRow: HTMLTableRowElement): void {
332	    closeContextMenu();
333	    const menu = document.createElement("ul");
334	    menu.setAttribute("role", "menu");
335	    menu.style.position = "absolute";
336	    menu.style.left = `${event.clientX}px`;
337	    menu.style.top = `${event.clientY}px`;
338	
339	    const entries: Array<{ action: "add-above" | "add-below"; label: string }> = [
340	      { action: "add-above", label: "Add row above" },
341	      { action: "add-below", label: "Add row below" },
342	    ];
343	
344	    for (const { action, label } of entries) {
345	      const item = document.createElement("li");
346	      item.setAttribute("role", "menuitem");
347	      item.setAttribute("data-action", action);
348	      item.textContent = label;
349	      item.addEventListener("click", () => {
350	        handleAddRow(anchorRow, action);
351	        closeContextMenu();
352	      });
353	      menu.appendChild(item);
354	    }
355	
356	    document.body.appendChild(menu);
357	  }
358	
359	  table.addEventListener("dblclick", (event) => {
360	    const target = event.target;
361	    if (!(target instanceof Element)) return;
362	    const cell = target.closest('td[data-residue-cell]');
363	    if (!(cell instanceof HTMLTableCellElement)) return;
364	    const forceKey = cell.getAttribute("data-force-id");
365	    const component = cell.getAttribute("data-component");
366	    if (forceKey === null || component === null) return;
367	
368	    const next = toggleComponent(getState(), forceKey, component);
369	    setState(next);
370	
371	    const coupled = effectiveComponents(next, forceKey).includes(component);
372	    cell.setAttribute("data-coupled", coupled ? "1" : "0");
373	    cell.textContent = coupled ? "1" : "";
374	
375	    applyInvalidMarks();
376	    options?.onChange?.();
377	  });
378	
379	  table.addEventListener("contextmenu", (event) => {
380	    const target = event.target;
381	    if (!(target instanceof Element)) return;
382	    const row = target.closest("tr.force-row");
383	    if (!(row instanceof HTMLTableRowElement)) return;
384	    event.preventDefault();
385	    openContextMenu(event, row);
386	  });
387	
388	  for (const detail of Array.from(table.querySelectorAll<HTMLElement>(".force-detail"))) {
389	    if (detail.querySelector("dl") === null) continue;
390	    const forceKey = detail.closest("th[data-force-id]")?.getAttribute("data-force-id");
391	    if (forceKey === null || forceKey === undefined) continue;
392	    appendEditButton(detail, forceKey);
393	  }
394	
395	  applyInvalidMarks();
396	}
